export const HARVEST_BROWSE = "(() => {\n    \"use strict\";\n\n    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n    const waitFor = async (check, { timeoutMs = 30000, intervalMs = 250 } = {}) => {\n        const deadline = Date.now() + timeoutMs;\n        for (;;) {\n            let value = null;\n            try { value = check(); } catch (e) { value = null; }\n            if (value) return value;\n            if (Date.now() >= deadline) return null;\n            await sleep(Math.min(intervalMs, Math.max(1, deadline - Date.now())));\n        }\n    };\n    const waitForStable = async (probe, { timeoutMs = 30000, intervalMs = 300, stableRounds = 2 } = {}) => {\n        const deadline = Date.now() + timeoutMs;\n        let lastSignature = null;\n        let stable = 0;\n        let value = null;\n        while (Date.now() < deadline) {\n            value = probe();\n            const signature = JSON.stringify(value);\n            if (signature === lastSignature) {\n                if (++stable >= stableRounds) return value;\n            } else {\n                stable = 0;\n                lastSignature = signature;\n            }\n            await sleep(intervalMs);\n        }\n        return value;\n    };\n    const readInitialData = (doc) => {\n        const candidates = [];\n        const byId = doc.querySelector(\"script#initial-data\");\n        if (byId) candidates.push(byId);\n        for (const script of doc.querySelectorAll('script[type=\"application/json\"]')) {\n            if (script !== byId) candidates.push(script);\n        }\n        for (const script of candidates) {\n            try {\n                const data = JSON.parse(script.textContent || \"null\");\n                if (data && typeof data === \"object\") return data;\n            } catch (e) {  }\n        }\n        return null;\n    };\n    const walkJson = (data, visit, maxDepth = 12) => {\n        const stack = [[data, 0]];\n        while (stack.length) {\n            const [value, depth] = stack.pop();\n            visit(value, depth);\n            if (depth >= maxDepth || !value || typeof value !== \"object\") continue;\n            const children = Array.isArray(value) ? value : Object.values(value);\n            for (let i = children.length - 1; i >= 0; i--) stack.push([children[i], depth + 1]);\n        }\n    };\n    const findObjects = (data, pred) => {\n        const found = [];\n        walkJson(data, (value) => {\n            if (value && typeof value === \"object\" && !Array.isArray(value) && pred(value)) {\n                found.push(value);\n            }\n        });\n        return found;\n    };\n    const findListParams = (data) => {\n        const paramObjects = findObjects(data, (o) =>\n            typeof o.page === \"number\" &&\n            (typeof o.limit === \"number\" || typeof o.perPage === \"number\"));\n        if (!paramObjects.length) return null;\n        const params = paramObjects[0];\n        const container = findObjects(data, (o) => o.params === params && typeof o.perPage === \"number\")[0];\n        return { params, perPage: container ? container.perPage : null };\n    };\n    const MANGA_PATH = /^\\/title\\/([a-z0-9]+)-/i;\n    const CHAPTER_PATH = /^\\/title\\/([a-z0-9]+)-[^/]+\\/(\\d+)-chapter-(\\d+(?:\\.\\d+)?)/i;\n    const pathOf = (href) => {\n        if (!href) return \"\";\n        if (/^https?:\\/\\//i.test(href)) {\n            try { return new URL(href).pathname; } catch (e) { return href; }\n        }\n        return href.split(/[?#]/)[0];\n    };\n    const parseMangaPath = (path) => {\n        const match = MANGA_PATH.exec(path || \"\");\n        return match ? { hid: match[1] } : null;\n    };\n    const parseChapterPath = (path) => {\n        const match = CHAPTER_PATH.exec(path || \"\");\n        return match ? { hid: match[1], id: Number(match[2]), number: parseFloat(match[3]) } : null;\n    };\n    const textOf = (el) => (el && el.textContent ? el.textContent : \"\").replace(/\\s+/g, \" \").trim();\n    const imageSrc = (img) => {\n        const src = img.getAttribute(\"src\") || \"\";\n        const lazy = img.getAttribute(\"data-src\") || img.getAttribute(\"data-lazy-src\") || \"\";\n        if (lazy && (!src || src.startsWith(\"data:\"))) return lazy;\n        return src || lazy || null;\n    };\n\n    const OPTIONS = Object.assign(\n        { timeoutMs: 30000, pollMs: 250, stableRounds: 2 },\n        window.__comixHarvestOptions || {});\n\n    const cardRoot = (anchor) => {\n        let el = anchor;\n        for (let depth = 0; el && depth < 5; depth++) {\n            if (el.querySelector && el.querySelector(\"img\")) return el;\n            el = el.parentElement;\n        }\n        return anchor;\n    };\n\n    const bestTitle = (entry) => {\n        const candidates = [];\n        for (const anchor of entry.anchors) {\n            const img = anchor.querySelector(\"img\");\n            if (img) candidates.push((img.getAttribute(\"alt\") || \"\").trim());\n            candidates.push(textOf(anchor));\n            candidates.push((anchor.getAttribute(\"aria-label\") || \"\").trim());\n            candidates.push((anchor.getAttribute(\"title\") || \"\").trim());\n        }\n        const usable = candidates.filter((t) => t && t.length >= 2 && t.length <= 140);\n        if (usable.length) return usable[0];\n        const slug = (entry.url.split(\"/\").pop() || \"\").replace(/^[a-z0-9]+-/i, \"\");\n        const words = slug.replace(/-/g, \" \").trim();\n        return words ? words.replace(/\\b\\w/g, (c) => c.toUpperCase()) : \"\";\n    };\n\n    const collect = () => {\n        const byHid = new Map();\n        for (const anchor of Array.from(document.querySelectorAll(\"a[href]\"))) {\n            const path = pathOf(anchor.getAttribute(\"href\") || \"\");\n            const manga = parseMangaPath(path);\n            if (!manga || parseChapterPath(path)) continue;\n            let entry = byHid.get(manga.hid);\n            if (!entry) {\n                entry = { hid: manga.hid, url: path, anchors: [], cover: null };\n                byHid.set(manga.hid, entry);\n            }\n            entry.anchors.push(anchor);\n            if (!entry.cover) {\n                const card = cardRoot(anchor);\n                const img = card ? card.querySelector(\"img\") : null;\n                if (img) entry.cover = imageSrc(img);\n            }\n        }\n        return Array.from(byHid.values()).map((entry) => ({\n            hid: entry.hid,\n            url: entry.url,\n            title: bestTitle(entry),\n            cover: entry.cover,\n        }));\n    };\n\n    const harvest = async () => {\n        const data = readInitialData(document);\n        const list = data ? findListParams(data) : null;\n        let items = collect();\n        if (!items.length) {\n\n            await waitFor(() => collect().length > 0 || null,\n                { timeoutMs: OPTIONS.timeoutMs, intervalMs: OPTIONS.pollMs });\n            items = collect();\n        }\n        if (items.length) {\n\n            items = await waitForStable(collect,\n                { timeoutMs: Math.min(OPTIONS.timeoutMs, 8000), intervalMs: OPTIONS.pollMs, stableRounds: OPTIONS.stableRounds }) || items;\n        }\n        const lateData = readInitialData(document);\n        const lateList = lateData ? findListParams(lateData) : null;\n        const finalList = lateList || list;\n        return {\n            page: \"browse\",\n            listParams: finalList ? finalList.params : null,\n            perPage: finalList ? finalList.perPage : null,\n            count: items.length,\n            items,\n        };\n    };\n\n    const done = (result) => {\n        window.__comixHarvest = result;\n        console.log(\"[comix-harvest:browse] \" + JSON.stringify(result));\n    };\n    window.__comixHarvestPromise = (async () => {\n        try {\n            const result = await harvest();\n            done(result);\n            return result;\n        } catch (e) {\n            const result = { page: \"browse\", error: String((e && e.message) || e), items: [], count: 0 };\n            done(result);\n            return result;\n        }\n    })();\n})();\n";

export const HARVEST_CHAPTERS = "(() => {\n    \"use strict\";\n\n    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n    const waitFor = async (check, { timeoutMs = 30000, intervalMs = 250 } = {}) => {\n        const deadline = Date.now() + timeoutMs;\n        for (;;) {\n            let value = null;\n            try { value = check(); } catch (e) { value = null; }\n            if (value) return value;\n            if (Date.now() >= deadline) return null;\n            await sleep(Math.min(intervalMs, Math.max(1, deadline - Date.now())));\n        }\n    };\n    const readInitialData = (doc) => {\n        const candidates = [];\n        const byId = doc.querySelector(\"script#initial-data\");\n        if (byId) candidates.push(byId);\n        for (const script of doc.querySelectorAll('script[type=\"application/json\"]')) {\n            if (script !== byId) candidates.push(script);\n        }\n        for (const script of candidates) {\n            try {\n                const data = JSON.parse(script.textContent || \"null\");\n                if (data && typeof data === \"object\") return data;\n            } catch (e) {  }\n        }\n        return null;\n    };\n    const walkJson = (data, visit, maxDepth = 12) => {\n        const stack = [[data, 0]];\n        while (stack.length) {\n            const [value, depth] = stack.pop();\n            visit(value, depth);\n            if (depth >= maxDepth || !value || typeof value !== \"object\") continue;\n            const children = Array.isArray(value) ? value : Object.values(value);\n            for (let i = children.length - 1; i >= 0; i--) stack.push([children[i], depth + 1]);\n        }\n    };\n    const findObjects = (data, pred) => {\n        const found = [];\n        walkJson(data, (value) => {\n            if (value && typeof value === \"object\" && !Array.isArray(value) && pred(value)) {\n                found.push(value);\n            }\n        });\n        return found;\n    };\n    const anchoredNumber = (data, anchor) => {\n        let best = null;\n        let bestCount = Infinity;\n        for (const obj of findObjects(data, (o) => Object.values(o).some((v) => v === anchor))) {\n            const numbers = Object.values(obj).filter((v) => typeof v === \"number\" && isFinite(v));\n            if (numbers.length && numbers.length < bestCount) {\n                best = numbers[0];\n                bestCount = numbers.length;\n            }\n        }\n        return best;\n    };\n    const MANGA_PATH = /^\\/title\\/([a-z0-9]+)-/i;\n    const CHAPTER_PATH = /^\\/title\\/([a-z0-9]+)-[^/]+\\/(\\d+)-chapter-(\\d+(?:\\.\\d+)?)/i;\n    const pathOf = (href) => {\n        if (!href) return \"\";\n        if (/^https?:\\/\\//i.test(href)) {\n            try { return new URL(href).pathname; } catch (e) { return href; }\n        }\n        return href.split(/[?#]/)[0];\n    };\n    // Recommended titles, chapters and other links off this page\n    const leavesPage = (el) => {\n        const path = pathOf(el.getAttribute(\"href\") || \"\");\n        return path !== \"\" && path !== location.pathname;\n    };\n    const parseMangaPath = (path) => {\n        const match = MANGA_PATH.exec(path || \"\");\n        return match ? { hid: match[1] } : null;\n    };\n    const parseChapterPath = (path) => {\n        const match = CHAPTER_PATH.exec(path || \"\");\n        return match ? { hid: match[1], id: Number(match[2]), number: parseFloat(match[3]) } : null;\n    };\n    const textOf = (el) => (el && el.textContent ? el.textContent : \"\").replace(/\\s+/g, \" \").trim();\n    // The signed-in hero \"Resume Ch. N\" link also points at a chapter\n    const isChapterRow = (anchor) => !!anchor.closest(\"li\");\n\n    const OPTIONS = Object.assign(\n        { timeoutMs: 45000, settleMs: 5000, pollMs: 100, maxRounds: 40, stopAtIds: [] },\n        window.__comixHarvestOptions || {});\n    const stopAt = new Set((OPTIONS.stopAtIds || []).map(Number));\n\n    const rowRoot = (anchor) => {\n        let el = anchor;\n        for (let depth = 0; depth < 4 && el.parentElement; depth++) {\n            const parent = el.parentElement;\n            const links = Array.from(parent.querySelectorAll(\"a[href]\"))\n                .filter((x) => parseChapterPath(pathOf(x.getAttribute(\"href\") || \"\")));\n            if (links.length !== 1) break;\n            el = parent;\n        }\n        return el;\n    };\n\n    // \"Ch.<n>\", then the name\n    const nameOf = (anchor) => Array.from(anchor.children).slice(1).map(textOf).join(\" \").trim();\n\n    // The group, or the uploader when there is none\n    const groupOf = (row) => {\n        if (!row) return null;\n        const group = row.querySelector('a[href^=\"/groups/\"]');\n        if (group && textOf(group)) {\n            const id = /^\\/groups\\/(\\d+)/.exec(group.getAttribute(\"href\") || \"\");\n            return { id: id ? Number(id[1]) : null, name: textOf(group) };\n        }\n        const uploader = row.querySelector('a[href^=\"/u/\"]');\n        return uploader && textOf(uploader) ? { id: null, name: textOf(uploader) } : null;\n    };\n\n    // \"70\" or \"1.2k\"\n    const votesOf = (row) => {\n        if (!row) return 0;\n        for (const span of row.querySelectorAll(\"span\")) {\n            const match = span.querySelector(\"svg\") && /^(\\d+(?:\\.\\d+)?)(k?)$/i.exec(textOf(span));\n            if (match) return Math.round(parseFloat(match[1]) * (match[2] ? 1000 : 1));\n        }\n        return 0;\n    };\n\n    const findMoreControl = (scope) => {\n        const inOrder = Array.from(document.querySelectorAll(\"a[href], button, [role='button']\"));\n        const orderOf = new Map(inOrder.map((el, i) => [el, i]));\n        let lastAnchorIdx = -1;\n        for (const el of inOrder) {\n            const href = el.getAttribute(\"href\");\n            if (href && parseChapterPath(pathOf(href)) && isChapterRow(el)) lastAnchorIdx = orderOf.get(el);\n        }\n        const currents = inOrder.filter((el) => (orderOf.get(el) ?? -1) > lastAnchorIdx &&\n            (el.getAttribute(\"aria-current\") === \"page\" || /\\bis-active\\b/.test(String(el.className || \"\"))) &&\n            /^\\d{1,4}$/.test((textOf(el) || \"\").trim()));\n        if (currents.length) {\n            const cur = currents[0];\n            const curNum = parseInt((textOf(cur) || \"\").trim(), 10);\n            let box = cur.parentElement;\n            for (let d = 0; d < 3 && box && box.tagName !== \"NAV\"; d++) box = box.parentElement;\n            const boxEls = Array.from((box || cur.parentElement || document)\n                .querySelectorAll(\"button, a[href], [role='button']\"));\n            let nextBtn = null;\n            let numbered = null;\n            for (const el of boxEls) {\n                if (el.disabled || el.getAttribute(\"aria-disabled\") === \"true\" || leavesPage(el)) continue;\n                const label = (textOf(el) || el.getAttribute(\"aria-label\") || \"\").trim();\n                if (/next/i.test(label)) nextBtn = el;\n                else if (/^\\d{1,4}$/.test(label) && parseInt(label, 10) === curNum + 1) numbered = el;\n            }\n            return nextBtn || numbered || null;\n        }\n        const controls = Array.from((scope || document).querySelectorAll(\"button, a[href], [role='button']\"));\n        const scored = [];\n        for (const el of controls) {\n            if (el.disabled) continue;\n            if (el.getAttribute(\"aria-current\") === \"page\") continue;\n            if (el.getAttribute(\"aria-disabled\") === \"true\") continue;\n            if (leavesPage(el)) continue;\n            if (/desc/i.test(String(el.className || \"\"))) continue;\n            const label = (textOf(el) || el.getAttribute(\"aria-label\") || \"\").trim();\n            if (!label) continue;\n            const afterList = lastAnchorIdx < 0 || (orderOf.get(el) ?? -1) > lastAnchorIdx;\n            let score = -1;\n            if (/next/i.test(label)) score = afterList ? 5 : 2;\n            else if (/load\\s*more|show\\s*more|view\\s*more|more\\s+chapters/i.test(label)) score = afterList ? 4 : -1;\n            else if (/^\\d{1,4}$/.test(label)) score = 1;\n            if (score >= 0) scored.push({ el, score });\n        }\n        scored.sort((a, b) => b.score - a.score);\n        return scored.length ? scored[0].el : null;\n    };\n\n    const describe = (el) => el ? {\n        tag: el.tagName,\n        cls: String(el.className || \"\").slice(0, 60),\n        label: (textOf(el) || el.getAttribute(\"aria-label\") || \"\").trim().slice(0, 40),\n    } : null;\n\n    const reportedTotal = () => {\n        if (!document.body) return null;\n        const m = /Showing\\s+\\d+\\s+to\\s+\\d+\\s+of\\s+([\\d,]+)\\s+items/i.exec(textOf(document.body));\n        return m ? parseInt(m[1].replace(/,/g, \"\"), 10) : null;\n    };\n\n    const harvest = async () => {\n        const here = parseMangaPath(location.pathname || pathOf(location.href || \"\"));\n        const hid = here ? here.hid : null;\n        const data = readInitialData(document);\n        const mangaId = data && hid ? anchoredNumber(data, hid) : null;\n\n        const byId = new Map();\n        const absorb = () => {\n            let added = 0;\n            for (const anchor of Array.from(document.querySelectorAll(\"a[href]\"))) {\n                const path = pathOf(anchor.getAttribute(\"href\") || \"\");\n                const chapter = parseChapterPath(path);\n                if (!chapter || !isChapterRow(anchor)) continue;\n                if (hid && chapter.hid !== hid) continue;\n                if (byId.has(chapter.id)) continue;\n                const row = rowRoot(anchor);\n                byId.set(chapter.id, {\n                    id: chapter.id,\n                    number: chapter.number,\n                    url: path,\n                    text: row ? textOf(row) : textOf(anchor),\n                    name: nameOf(anchor),\n                    votes: votesOf(row),\n                    group: groupOf(row),\n                });\n                added++;\n            }\n            return added;\n        };\n        const reachedKnown = () => Array.from(byId.keys()).some((id) => stopAt.has(id));\n\n        await waitFor(() => (absorb(), byId.size > 0) || null,\n            { timeoutMs: OPTIONS.timeoutMs, intervalMs: OPTIONS.pollMs });\n\n        const sectionRoot = () => {\n            const first = Array.from(document.querySelectorAll(\"a[href]\"))\n                .find((a) => {\n                    const c = parseChapterPath(pathOf(a.getAttribute(\"href\") || \"\"));\n                    return c && (!hid || c.hid === hid) && isChapterRow(a);\n                });\n            if (!first) return document.body;\n            const rendered = Array.from(document.querySelectorAll(\"a[href]\"))\n                .filter((a) => {\n                    const c = parseChapterPath(pathOf(a.getAttribute(\"href\") || \"\"));\n                    return c && (!hid || c.hid === hid) && isChapterRow(a);\n                }).length;\n            let root = first;\n            for (let depth = 0; depth < 12 && root.parentElement; depth++) {\n                const parent = root.parentElement;\n                const inside = Array.from(parent.querySelectorAll(\"a[href]\"))\n                    .filter((a) => {\n                        const c = parseChapterPath(pathOf(a.getAttribute(\"href\") || \"\"));\n                        return c && (!hid || c.hid === hid) && isChapterRow(a);\n                    }).length;\n                if (inside >= rendered) root = parent;\n                else break;\n            }\n            return root;\n        };\n\n        const activate = async (el, entry) => {\n            const r0 = el.getBoundingClientRect();\n            const inView = r0.width > 0 && r0.top >= 0 && r0.bottom <= window.innerHeight &&\n                r0.left >= 0 && r0.right <= window.innerWidth;\n            if (!inView) {\n                try { el.scrollIntoView({ block: \"center\" }); } catch (e) {}\n                await sleep(350);\n            } else {\n                await sleep(60);\n            }\n            let tapped = false;\n            if (typeof window.__comixNativeTap === \"function\") {\n                const r = el.getBoundingClientRect();\n                if (entry) {\n                    entry.rect = [Math.round(r.left), Math.round(r.top), Math.round(r.width), Math.round(r.height)];\n                    const at = document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2);\n                    entry.atPoint = describe(at);\n                }\n                if (r.width > 0 && r.height > 0) {\n                    try {\n                        window.__comixNativeTap(r.left + r.width / 2, r.top + r.height / 2);\n                        tapped = true;\n                    } catch (e) {}\n                }\n            }\n            if (!tapped) {\n                try { el.click(); } catch (e) {}\n            }\n            return tapped;\n        };\n\n        const diag = [];\n        let rounds = 0;\n        let complete = false;\n        let stoppedAtKnown = reachedKnown();\n        while (!stoppedAtKnown && rounds < OPTIONS.maxRounds) {\n            let control = findMoreControl(sectionRoot());\n            if (!control) control = findMoreControl(document);\n            if (!control) {\n                complete = byId.size > 0;\n                break;\n            }\n            const before = byId.size;\n            rounds++;\n            const entry = {\n                round: rounds,\n                control: describe(control),\n                before,\n                tapBridge: typeof window.__comixNativeTap === \"function\",\n                total: reportedTotal(),\n            };\n            const usedTap = await activate(control, entry);\n            entry.method = usedTap ? \"tap\" : \"click\";\n            let grew = await waitFor(() => (absorb(), byId.size > before) || null,\n                { timeoutMs: OPTIONS.settleMs, intervalMs: OPTIONS.pollMs });\n            if (!grew && !reachedKnown()) {\n                await activate(control, null);\n                grew = await waitFor(() => (absorb(), byId.size > before) || null,\n                    { timeoutMs: OPTIONS.settleMs, intervalMs: OPTIONS.pollMs });\n            }\n            if (!grew && !reachedKnown()) {\n                try { control.click(); } catch (e) {}\n                grew = await waitFor(() => (absorb(), byId.size > before) || null,\n                    { timeoutMs: OPTIONS.settleMs, intervalMs: OPTIONS.pollMs });\n            }\n            entry.after = byId.size;\n            entry.url = location.href;\n            diag.push(entry);\n            const now = parseMangaPath(location.pathname);\n            if (hid && (!now || now.hid !== hid)) throw new Error(\"Left the title page for \" + location.pathname);\n            if (reachedKnown()) {\n                stoppedAtKnown = true;\n                break;\n            }\n            if (!grew) {\n                complete = byId.size > 0;\n                break;\n            }\n        }\n\n        // Item count seen before a failed page cleared the list\n        const total = reportedTotal() ?? diag.map((e) => e.total).filter((t) => t != null).pop() ?? null;\n        if (total != null && byId.size < total && !stoppedAtKnown) complete = false;\n        const chapters = Array.from(byId.values())\n            .sort((a, b) => (b.number - a.number) || (b.id - a.id));\n        return {\n            page: \"manga\",\n            hid,\n            mangaId,\n            count: chapters.length,\n            complete,\n            stoppedAtKnown,\n            rounds,\n            reportedTotal: total,\n            diag: diag.slice(0, 12),\n            chapters,\n        };\n    };\n\n    const done = (result) => {\n        window.__comixHarvest = result;\n        console.log(\"[comix-harvest:chapters] \" + JSON.stringify(result));\n    };\n    window.__comixHarvestPromise = (async () => {\n        try {\n            const result = await harvest();\n            done(result);\n            return result;\n        } catch (e) {\n            const result = { page: \"manga\", error: String((e && e.message) || e), chapters: [], count: 0 };\n            done(result);\n            return result;\n        }\n    })();\n})();\n";

export const CHAPTER_PAGES = "// Every build you re-mangle, this file gets a little shorter. Love, the mouse.\n// Posts \"total\", then \"page\" or \"miss\" per page, then \"done\"; window[seekName] is [page waited on, retry count]\n(pass, reject, seekName, knownIndices) => {\n    const startedAt = Date.now();\n    const FIRST_PAGE_TIMEOUT_MS = 30000;\n    const WALK_TIMEOUT_MS = 220000;\n    const SLOT_TIMEOUT_MS = 15000;\n    const SETTLE_MS = 100;\n    const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));\n\n    let container = null;\n    let slots = [];\n    let total = 0;\n    const shapeOf = (element) => element.tagName + \".\" + (element.getAttribute(\"class\") || \"\");\n    // Pages: same-shaped children holding off-site images, innermost and tallest in a scroller\n    const site = location.hostname.replace(/^www\\./, \"\");\n    const isForeignImage = (img) => {\n        try {\n            const host = new URL(img.getAttribute(\"src\") || \"\", location.href).hostname;\n            return host !== site && !host.endsWith(\".\" + site);\n        } catch (e) {\n            return false;\n        }\n    };\n    const scrolls = (element) => element.scrollHeight > element.clientHeight &&\n        (element === document.scrollingElement || /(auto|scroll)/.test(getComputedStyle(element).overflowY));\n    const insideScroller = (element) => {\n        for (let parent = element.parentElement; parent; parent = parent.parentElement) if (scrolls(parent)) return true;\n        return false;\n    };\n    const findReader = () => {\n        const totals = new Set();\n        for (const element of document.body.querySelectorAll(\"*\")) {\n            if (element.firstElementChild) continue;\n            const match = /^\\s*\\d+\\s*\\/\\s*(\\d+)\\s*$/.exec(element.textContent || \"\");\n            if (match) totals.add(parseInt(match[1], 10));\n        }\n        const matches = [];\n        for (const element of document.body.querySelectorAll(\"*\")) {\n            const withImage = Array.prototype.find.call(element.children,\n                (child) => Array.prototype.some.call(child.querySelectorAll(\"img\"), isForeignImage));\n            if (!withImage) continue;\n            const shape = shapeOf(withImage);\n            const count = Array.prototype.filter.call(element.children, (child) => shapeOf(child) === shape).length;\n            if (totals.size && !totals.has(count)) continue;\n            if (insideScroller(element)) matches.push({ element, shape });\n        }\n        // Wrappers match too; keep the innermost\n        let best = null;\n        for (const match of matches) {\n            if (matches.some((other) => other !== match && match.element.contains(other.element))) continue;\n            if (!best || match.element.offsetHeight > best.element.offsetHeight) best = match;\n        }\n        return best && {\n            element: best.element,\n            slots: Array.prototype.filter.call(best.element.children, (child) => shapeOf(child) === best.shape),\n        };\n    };\n    // Settled after two matching polls; found again if replaced\n    let candidate = null;\n    const attachReader = () => {\n        if (container && container.isConnected) return true;\n        const reader = document.body && findReader();\n        const settled = reader && candidate && reader.element === candidate.element &&\n            reader.slots.length === candidate.slots.length;\n        candidate = reader;\n        if (!settled) return false;\n        ({ element: container, slots } = reader);\n        total = slots.length;\n        container.querySelectorAll(\"img[src]\").forEach(record);\n        return true;\n    };\n    const slotIndex = (img) => {\n        let slot = img;\n        while (slot.parentElement && slot.parentElement !== container) slot = slot.parentElement;\n        return slots.indexOf(slot);\n    };\n\n    // Latest url per page; the reader swaps hosts on failure\n    const captured = new Map(knownIndices.map((index) => [index, null]));\n    const missed = new Set();\n    const record = (img) => {\n        if (!container || !attachReader()) return;\n        let url;\n        try { url = new URL(img.getAttribute(\"src\") || \"\", location.href); } catch (e) { return; }\n        if (!/^https?:$/.test(url.protocol)) return;\n        const index = slotIndex(img);\n        if (index < 0 || captured.get(index) === url.href) return;\n        captured.set(index, url.href);\n        missed.delete(index);\n        pass(JSON.stringify({ type: \"page\", index, url: url.href }));\n    };\n\n    // A saved paged reader becomes the strip until the reader starts\n    const savedReader = {};\n    for (let i = 0; i < localStorage.length; i++) {\n        const key = localStorage.key(i);\n        try {\n            const raw = localStorage.getItem(key);\n            const stored = JSON.parse(raw);\n            if (stored && stored.state && \"readingDirection\" in stored.state && stored.state.readingDirection !== \"ttb\") {\n                savedReader[key] = raw;\n                stored.state.readingDirection = \"ttb\";\n                localStorage.setItem(key, JSON.stringify(stored));\n            }\n        } catch (e) {}\n    }\n    const restoreReader = () => {\n        Object.entries(savedReader).forEach(([key, raw]) => localStorage.setItem(key, raw));\n        Object.keys(savedReader).forEach((key) => delete savedReader[key]);\n    };\n\n    // Started at document-start, before the reader runs\n    const recordImage = (node) => {\n        if (node.tagName === \"IMG\") record(node);\n        else if (node.querySelectorAll) node.querySelectorAll(\"img[src]\").forEach(record);\n    };\n    new MutationObserver((mutations) => {\n        for (const mutation of mutations) {\n            if (mutation.type === \"attributes\") recordImage(mutation.target);\n            else mutation.addedNodes.forEach(recordImage);\n        }\n    }).observe(document, { subtree: true, childList: true, attributes: true, attributeFilter: [\"src\"] });\n\n    const waitForReader = async () => {\n        while (Date.now() < startedAt + FIRST_PAGE_TIMEOUT_MS) {\n            if (attachReader()) return;\n            await sleep(200);\n        }\n        throw new Error(\"The reader didn't load any pages\");\n    };\n\n    const waited = new Map();\n    let retries = 0;\n    const readSeek = () => {\n        const value = window[seekName];\n        if (!Array.isArray(value)) return -1;\n        const [seek, retry] = value;\n        if (retry !== retries) {\n            retries = retry;\n            if (missed.delete(seek)) waited.delete(seek);\n        }\n        return seek;\n    };\n\n    const walk = async () => {\n        await waitForReader();\n        restoreReader();\n        pass(JSON.stringify({ type: \"total\", total }));\n        const done = (i) => captured.has(i) || missed.has(i);\n        while (Date.now() < startedAt + WALK_TIMEOUT_MS) {\n            // Waited-on page first, then forward, then the rest\n            const seek = readSeek();\n            let target = seek >= 0 && seek < total && !done(seek) ? seek : -1;\n            for (let i = Math.max(seek, 0); target < 0 && i < total; i++) if (!done(i)) target = i;\n            for (let i = 0; target < 0 && i < total; i++) if (!done(i)) target = i;\n            if (target < 0) break;\n\n            const time = (waited.get(target) || 0) + SETTLE_MS;\n            waited.set(target, time);\n            if (time > SLOT_TIMEOUT_MS) {\n                missed.add(target);\n                pass(JSON.stringify({ type: \"miss\", index: target }));\n                continue;\n            }\n            // Pages the observer saw before they joined the list\n            if (attachReader()) {\n                container.querySelectorAll(\"img[src]\").forEach(record);\n                slots[target].scrollIntoView({ block: \"center\" });\n            }\n            await sleep(SETTLE_MS);\n        }\n        pass(JSON.stringify({ type: \"done\" }));\n    };\n\n    walk().catch((e) => {\n        restoreReader();\n        reject(e && e.message || String(e));\n    });\n}\n";

export const SOLVE_CAPTCHA = "// Answers the site's rotate or click-the-shapes captcha, then posts the solved message the site's own captcha page sends\n// Shows the site's own captcha page when it is a Cloudflare Turnstile check\n// Rotation search ported from https://github.com/nekomangaorg/Neko (ComixWafSolver)\n// Shapes: go-captcha's stock set (https://github.com/wenlng/go-captcha-assets, Apache-2.0) as 60x60 bitmaps\n(reject) => {\n    const SHAPES = [\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n        \"\",\n    ];\n    const SHAPE_SIZE = 60;\n    const MASTER_PALETTE = [\"#fde98e\", \"#60c1ff\", \"#fcb08e\", \"#fb88ff\", \"#b4fed4\", \"#cbfaa9\", \"#78d6f8\"];\n    const THUMB_PALETTE = [\"#1f55c4\", \"#780592\", \"#2f6b00\", \"#910000\", \"#864401\", \"#675901\", \"#016e5c\"];\n    const GRID = 40;\n    const SIZES = Array.from({ length: 19 }, (_, i) => i + 18);\n    const ANGLES = Array.from({ length: 120 }, (_, i) => i * 3).filter((a) => (a >= 15 && a <= 75) || (a >= 285 && a <= 345));\n    const CONFIDENT_MARGIN = 2.2;\n    const CHALLENGES_PER_ROUND = 5;\n    const ROUNDS = 3;\n    const TURNSTILE_SCRIPT = \"challenges.cloudflare.com/turnstile\";\n    const TURNSTILE_WAIT_MS = 20000;\n\n    const rgb = (hex) => [1, 3, 5].map((i) => parseInt(hex.slice(i, i + 2), 16));\n    const masterPalette = MASTER_PALETTE.map(rgb);\n    const thumbPalette = THUMB_PALETTE.map(rgb);\n\n    const loadImage = (src) => new Promise((resolve, fail) => {\n        const image = new Image();\n        image.onload = () => resolve(image);\n        image.onerror = () => fail(new Error(\"Could not decode the captcha image\"));\n        image.src = src;\n    });\n\n    const imageData = (image) => {\n        const canvas = document.createElement(\"canvas\");\n        canvas.width = image.width;\n        canvas.height = image.height;\n        const context = canvas.getContext(\"2d\");\n        context.drawImage(image, 0, 0);\n        return context.getImageData(0, 0, image.width, image.height);\n    };\n\n    const dilate = (mask, w, h, r) => {\n        const out = new Uint8Array(w * h);\n        for (let y = 0; y < h; y++) {\n            for (let x = 0; x < w; x++) {\n                if (!mask[y * w + x]) continue;\n                for (let dy = -r; dy <= r; dy++) {\n                    const ny = y + dy;\n                    if (ny < 0 || ny >= h) continue;\n                    for (let dx = -r; dx <= r; dx++) {\n                        const nx = x + dx;\n                        if (nx >= 0 && nx < w) out[ny * w + nx] = 1;\n                    }\n                }\n            }\n        }\n        return out;\n    };\n\n    const invert = (mask) => mask.map((v) => 1 - v);\n    const erode = (mask, w, h, r) => invert(dilate(invert(mask), w, h, r));\n\n    const neighbours = (mask, w, h) => {\n        const out = new Uint8Array(w * h);\n        for (let y = 0; y < h; y++) {\n            for (let x = 0; x < w; x++) {\n                let n = 0;\n                for (let dy = -1; dy <= 1; dy++) {\n                    for (let dx = -1; dx <= 1; dx++) {\n                        if (!dy && !dx) continue;\n                        const ny = y + dy, nx = x + dx;\n                        if (ny >= 0 && ny < h && nx >= 0 && nx < w) n += mask[ny * w + nx];\n                    }\n                }\n                out[y * w + x] = n;\n            }\n        }\n        return out;\n    };\n\n    // 4-connected components as lists of pixel indices\n    const components = (mask, w, h) => {\n        const seen = new Uint8Array(w * h);\n        const out = [];\n        for (let start = 0; start < w * h; start++) {\n            if (!mask[start] || seen[start]) continue;\n            const stack = [start];\n            const pixels = [];\n            seen[start] = 1;\n            while (stack.length) {\n                const p = stack.pop();\n                pixels.push(p);\n                const x = p % w, y = (p - x) / w;\n                for (const [nx, ny] of [[x + 1, y], [x - 1, y], [x, y + 1], [x, y - 1]]) {\n                    if (nx < 0 || nx >= w || ny < 0 || ny >= h) continue;\n                    const q = ny * w + nx;\n                    if (mask[q] && !seen[q]) {\n                        seen[q] = 1;\n                        stack.push(q);\n                    }\n                }\n            }\n            out.push(pixels);\n        }\n        return out;\n    };\n\n    const bounds = (pixels, w) => {\n        let minX = Infinity, maxX = -1, minY = Infinity, maxY = -1, sumX = 0, sumY = 0;\n        for (const p of pixels) {\n            const x = p % w, y = (p - x) / w;\n            minX = Math.min(minX, x); maxX = Math.max(maxX, x);\n            minY = Math.min(minY, y); maxY = Math.max(maxY, y);\n            sumX += x; sumY += y;\n        }\n        return { minX, maxX, minY, maxY, cx: sumX / pixels.length, cy: sumY / pixels.length };\n    };\n\n    // Area-normalised, centroid-centred GRID x GRID mask, sampled back from the source pixels\n    const normalise = (pixels, w) => {\n        const b = bounds(pixels, w);\n        const bw = b.maxX - b.minX + 1, bh = b.maxY - b.minY + 1;\n        const src = new Uint8Array(bw * bh);\n        for (const p of pixels) {\n            const x = p % w, y = (p - x) / w;\n            src[(y - b.minY) * bw + (x - b.minX)] = 1;\n        }\n        const scale = Math.sqrt(pixels.length) / (GRID * 0.42);\n        const out = new Uint8Array(GRID * GRID);\n        for (let gy = 0; gy < GRID; gy++) {\n            const sy = Math.floor((gy - GRID / 2 + 0.5) * scale + b.cy - b.minY + 0.5);\n            if (sy < 0 || sy >= bh) continue;\n            for (let gx = 0; gx < GRID; gx++) {\n                const sx = Math.floor((gx - GRID / 2 + 0.5) * scale + b.cx - b.minX + 0.5);\n                if (sx >= 0 && sx < bw) out[gy * GRID + gx] = src[sy * bw + sx];\n            }\n        }\n        return out;\n    };\n\n    const shapeBits = SHAPES.map((encoded) => {\n        const bytes = atob(encoded);\n        const bits = new Uint8Array(SHAPE_SIZE * SHAPE_SIZE);\n        for (let i = 0; i < bits.length; i++) bits[i] = (bytes.charCodeAt(i >> 3) >> (7 - (i & 7))) & 1;\n        return bits;\n    });\n\n    // Shape scaled to (size+10)^2 like go-captcha draws it, by averaging 4x4 samples per pixel\n    const resized = new Map();\n    const resize = (shape, size) => {\n        const key = `${shape}/${size}`;\n        if (!resized.has(key)) {\n            const s = size + 10, f = SHAPE_SIZE / s, bits = shapeBits[shape];\n            const out = new Uint8Array(s * s);\n            let area = 0;\n            for (let y = 0; y < s; y++) {\n                for (let x = 0; x < s; x++) {\n                    let sum = 0;\n                    for (let i = 0; i < 4; i++) {\n                        for (let j = 0; j < 4; j++) {\n                            sum += bits[Math.floor((y + (i + 0.5) / 4) * f) * SHAPE_SIZE + Math.floor((x + (j + 0.5) / 4) * f)];\n                        }\n                    }\n                    if (sum > 8) { out[y * s + x] = 1; area++; }\n                }\n            }\n            resized.set(key, { side: s, mask: out, area });\n        }\n        return resized.get(key);\n    };\n\n    const templates = new Map();\n    const template = (shape, size, thumb) => {\n        const key = `${shape}/${size}/${thumb}`;\n        if (!templates.has(key)) {\n            const { side, mask } = resize(shape, size);\n            const pad = 3, out = side + 2 * pad + Math.ceil(side * 0.5);\n            const c = (side - 1) / 2, oc = (out - 1) / 2;\n            const rotations = ANGLES.map((angle) => {\n                const rad = (angle * Math.PI) / 180, cos = Math.cos(rad), sin = Math.sin(rad);\n                let rotated = new Uint8Array(out * out);\n                for (let y = 0; y < out; y++) {\n                    for (let x = 0; x < out; x++) {\n                        const dx = x - oc, dy = y - oc;\n                        const sx = Math.round(cos * dx - sin * dy + c), sy = Math.round(sin * dx + cos * dy + c);\n                        if (sx >= 0 && sx < side && sy >= 0 && sy < side) rotated[y * out + x] = mask[sy * side + sx];\n                    }\n                }\n                if (thumb) rotated = thumbClean(rotated, out, out);\n                const pixels = [];\n                rotated.forEach((v, i) => { if (v) pixels.push(i); });\n                return normalise(pixels, out);\n            });\n            templates.set(key, rotations);\n        }\n        return templates.get(key);\n    };\n\n    // Strip shapes: bridge the noise lines drawn across them, then drop line/mark pixels\n    const thumbClean = (mask, w, h) => {\n        const closed = erode(dilate(mask, w, h, 1), w, h, 1).map((v, i) => v | mask[i]);\n        const n = neighbours(closed, w, h);\n        return closed.map((v, i) => (v && n[i] >= 4 ? 1 : 0));\n    };\n\n    const scores = (blob, thumb) => SHAPES.map((_, shape) => {\n        const size = SIZES.reduce((a, b) => (Math.abs(resize(shape, b).area - blob.area) < Math.abs(resize(shape, a).area - blob.area) ? b : a));\n        let best = 0;\n        for (const t of template(shape, size, thumb)) {\n            let inter = 0, union = 0;\n            for (let i = 0; i < t.length; i++) {\n                inter += t[i] & blob.mask[i];\n                union += t[i] | blob.mask[i];\n            }\n            best = Math.max(best, inter / union);\n        }\n        return best;\n    });\n\n    const nearestColour = (data, palette) => {\n        const n = data.length / 4;\n        const nearest = new Uint8Array(n), distance = new Float32Array(n);\n        for (let p = 0; p < n; p++) {\n            let best = 0, bestD = Infinity;\n            for (let k = 0; k < palette.length; k++) {\n                const dr = data[p * 4] - palette[k][0], dg = data[p * 4 + 1] - palette[k][1], db = data[p * 4 + 2] - palette[k][2];\n                const d = dr * dr + dg * dg + db * db;\n                if (d < bestD) { bestD = d; best = k; }\n            }\n            nearest[p] = best;\n            distance[p] = Math.sqrt(bestD);\n        }\n        return { nearest, distance };\n    };\n\n    // Picture shapes: flat palette-coloured blobs of shape size with a dark shadow beside them\n    const masterBlobs = ({ width: w, height: h, data }) => {\n        const { nearest, distance } = nearestColour(data, masterPalette);\n        const dark = new Uint8Array(w * h);\n        for (let p = 0; p < w * h; p++) dark[p] = data[p * 4] + data[p * 4 + 1] + data[p * 4 + 2] < 150 ? 1 : 0;\n        const blobs = [];\n        const tooBig = (pixels) => {\n            const b = bounds(pixels, w);\n            return pixels.length > 1400 || b.maxY - b.minY >= 60 || b.maxX - b.minX >= 60;\n        };\n        // Petals of one shape don't touch: join pieces within `group` px, splitting too-big groups finer\n        const pieces = (pixels, group, found) => {\n            const sub = new Uint8Array(w * h);\n            for (const p of pixels) sub[p] = 1;\n            for (const joined of components(group ? dilate(sub, w, h, group) : sub, w, h)) {\n                const own = joined.filter((p) => sub[p]);\n                if (!own.length) continue;\n                if (group && tooBig(own)) pieces(own, group - 1, found);\n                else found.push(own);\n            }\n            return found;\n        };\n        for (let k = 0; k < masterPalette.length; k++) {\n            const pixels = [];\n            for (let p = 0; p < w * h; p++) if (nearest[p] === k && distance[p] < 40) pixels.push(p);\n            for (const blob of pieces(pixels, 2, [])) {\n                const b = bounds(blob, w);\n                const bh = b.maxY - b.minY + 1, bw = b.maxX - b.minX + 1;\n                if (blob.length < 120 || blob.length > 1400 || bh < 14 || bh > 60 || bw < 14 || bw > 60) continue;\n                const own = new Uint8Array(w * h);\n                for (const p of blob) own[p] = 1;\n                const ring = dilate(own, w, h, 2);\n                let shadow = 0;\n                for (let p = 0; p < w * h; p++) if (ring[p] && !own[p] && dark[p]) shadow++;\n                const meanDistance = blob.reduce((s, p) => s + distance[p], 0) / blob.length;\n                if (shadow < 3 || meanDistance > 20) continue;\n                blobs.push({ x: Math.round(b.cx), y: Math.round(b.cy), area: blob.length, mask: normalise(blob, w) });\n            }\n        }\n        return blobs;\n    };\n\n    // Strip shapes, left to right: the largest single-colour blobs once the noise is cleaned off\n    const thumbBlobs = ({ width: w, height: h, data }, count) => {\n        const { nearest, distance } = nearestColour(data, thumbPalette);\n        const found = [];\n        for (let k = 0; k < thumbPalette.length; k++) {\n            const mask = new Uint8Array(w * h);\n            for (let p = 0; p < w * h; p++) mask[p] = data[p * 4 + 3] > 128 && distance[p] < 60 && nearest[p] === k ? 1 : 0;\n            found.push(...components(thumbClean(mask, w, h), w, h));\n        }\n        found.sort((a, b) => b.length - a.length);\n        return found.slice(0, count)\n            .sort((a, b) => bounds(a, w).cx - bounds(b, w).cx)\n            .map((pixels) => {\n                const own = new Uint8Array(w * h);\n                for (const p of pixels) own[p] = 1;\n                const opened = dilate(erode(own, w, h, 1), w, h, 1);\n                const kept = pixels.filter((p) => opened[p]);\n                const shape = kept.length >= 0.6 * pixels.length ? kept : pixels;\n                return { area: shape.length, mask: normalise(shape, w) };\n            });\n    };\n\n    const softmax = (values) => {\n        const max = Math.max(...values);\n        const e = values.map((v) => Math.exp((v - max) / 0.01));\n        const sum = e.reduce((a, b) => a + b, 0);\n        return e.map((v) => v / sum);\n    };\n\n    // Rotate captcha: clockwise angle that lines the piece up with the picture's centre\n    const planRotate = async (challenge) => {\n        const [image, piece] = await Promise.all([loadImage(challenge.image_base64), loadImage(challenge.thumb_base64)]);\n        const size = piece.width, offset = Math.floor((image.width - size) / 2);\n        const reference = imageData(image), rotated = imageData(piece).data;\n        const gray = (data, i) => (data[i * 4] + data[i * 4 + 1] + data[i * 4 + 2]) / 3;\n        const center = (size - 1) / 2, scale = size / 128;\n        let bestAngle = 0, bestScore = Infinity;\n        for (let degrees = 0; degrees < 360; degrees++) {\n            const rad = (degrees * Math.PI) / 180, cos = Math.cos(rad), sin = Math.sin(rad);\n            let sum = 0, valid = 0;\n            for (let i = 0; i < 128 * 128; i++) {\n                const gx = (i % 128) * scale, gy = Math.floor(i / 128) * scale;\n                const vx = gx - center, vy = gy - center;\n                const x = center + vx * cos + vy * sin, y = center - vx * sin + vy * cos;\n                if (x < 0 || x >= size || y < 0 || y >= size) continue;\n                const index = Math.floor(y) * size + Math.floor(x);\n                if (rotated[index * 4 + 3] <= 128) continue;\n                const diff = gray(reference.data, (offset + Math.floor(gy)) * reference.width + offset + Math.floor(gx)) - gray(rotated, index);\n                sum += diff * diff;\n                valid++;\n            }\n            if (valid >= 100 && sum / valid < bestScore) {\n                bestScore = sum / valid;\n                bestAngle = degrees;\n            }\n        }\n        return { margin: Infinity, answer: { angle: bestAngle } };\n    };\n\n    // Click captcha: picture blob for each strip shape, and how far the best pairing beats the runner-up\n    const planClick = async (challenge) => {\n        const [image, thumb] = await Promise.all([loadImage(challenge.image_base64), loadImage(challenge.thumb_base64)]);\n        const masters = masterBlobs(imageData(image));\n        const thumbs = thumbBlobs(imageData(thumb), challenge.count);\n        if (thumbs.length < challenge.count || masters.length < thumbs.length) return { margin: -Infinity };\n        const mp = masters.map((m) => softmax(scores(m, false)));\n        const tp = thumbs.map((t) => softmax(scores(t, true)));\n        const similarity = tp.map((t) => mp.map((m) => Math.log(t.reduce((s, v, i) => s + v * m[i], 0) + 1e-12)));\n        let best = { total: -Infinity }, second = -Infinity;\n        const search = (i, used, total, picks) => {\n            if (i === thumbs.length) {\n                if (total > best.total) { second = best.total; best = { total, picks: [...picks] }; } else if (total > second) second = total;\n                return;\n            }\n            for (let j = 0; j < masters.length; j++) {\n                if (used & (1 << j)) continue;\n                picks.push(j);\n                search(i + 1, used | (1 << j), total + similarity[i][j], picks);\n                picks.pop();\n            }\n        };\n        search(0, 0, 0, []);\n        return {\n            margin: (best.total - second) / thumbs.length,\n            answer: { dots: best.picks.flatMap((j) => [masters[j].x, masters[j].y]).join(\",\") },\n        };\n    };\n\n    class UnknownCaptcha extends Error {}\n\n    const json = async (response) => {\n        if (!response.ok) throw new Error(`HTTP error ${response.status}`);\n        return response.json();\n    };\n\n    // Up to CHALLENGES_PER_ROUND challenges; answers the first confident one, else the most confident\n    const round = async () => {\n        let best = null;\n        for (let i = 0; i < CHALLENGES_PER_ROUND; i++) {\n            const challenge = await json(await fetch(\"/@waf/generate\", { headers: { Accept: \"application/json\" } }));\n            if (!challenge.image_base64 || !challenge.thumb_base64) throw new UnknownCaptcha();\n            let plan;\n            if (challenge.count > 0) plan = planClick;\n            else if (challenge.thumb_size > 0) plan = planRotate;\n            else throw new UnknownCaptcha();\n            const attempt = { challenge, ...(await plan(challenge)) };\n            if (!best || attempt.margin > best.margin) best = attempt;\n            if (best.margin >= CONFIDENT_MARGIN) break;\n        }\n        if (!best.answer) return false;\n        const response = await fetch(\"/@waf/verify\", {\n            method: \"POST\",\n            headers: { \"Content-Type\": \"application/json\" },\n            body: JSON.stringify({ captcha_id: best.challenge.captcha_id, ...best.answer }),\n        });\n        return (await json(response)).success === true;\n    };\n\n    // Site's own page in place of this one; it posts the solved message itself\n    const showSitePage = (page) => {\n        const timer = setTimeout(() => reject(\"Couldn't pass the site's Cloudflare check, open in WebView to pass it\"), TURNSTILE_WAIT_MS);\n        parent.addEventListener(\"message\", (event) => {\n            if (event.data?.type === \"waf-captcha-solved\") clearTimeout(timer);\n        });\n        document.open();\n        document.write(page);\n        document.close();\n    };\n\n    (async () => {\n        const response = await fetch(location.pathname);\n        if (!response.ok) throw new Error(`HTTP error ${response.status}`);\n        const page = await response.text();\n        if (page.includes(TURNSTILE_SCRIPT)) return showSitePage(page);\n        for (let i = 0; i < ROUNDS; i++) {\n            if (await round()) {\n                parent.postMessage({ type: \"waf-captcha-solved\" }, location.origin);\n                return;\n            }\n        }\n        reject(\"Couldn't solve the site's captcha, open in WebView to solve it\");\n    })().catch((error) => reject(\n        error instanceof UnknownCaptcha\n            ? \"The site changed its captcha, open in WebView to solve it\"\n            : `Couldn't solve the site's captcha (${error.message}), open in WebView to solve it`,\n    ));\n}\n";
